# kaliru plugin layer, python side (module `_k`; docs/PLUGINS.md).
#
# The mirror modules (src/plugins/mirror/, generated by tools/gen_mirror.py)
# define Kalico's klippy classes as python classes whose methods call into
# kaliru through the native module `_kaliru`. This module supplies their
# building blocks and the import machinery:
#  - Object / Meta: the root of every mirrored class. Meta tells kaliru when a
#    mirrored method is replaced on a class or overridden by a subclass, and
#    Object.__setattr__ when it is replaced on an instance, so kaliru's own
#    calls of that method go to the python replacement
#  - Attr: an instance attribute that lives in kaliru (data descriptor)
#  - module_getattr: module names that are not copied into a mirror module
#    resolve on first access (PEP 562)
#  - MirrorFinder: `klippy.*` imports come from the mirror modules, except
#    modules a mirror does not exist for (third-party extras and plugins),
#    which are files under the klippy directory; plus Kalico's compat aliases
#    (`import mcu` is `klippy.mcu`, klippy/compat.py)
import importlib.abc
import importlib.machinery
import importlib.util
import os
import sys

import _kaliru as _n

call = _n.call
fcall = _n.fcall
new = _n.new


class Meta(type):
    def __init__(cls, name, bases, ns):
        super().__init__(name, bases, ns)
        if not ns.get("__kaliru_mirror__", False):
            # a plugin's subclass of a mirrored class: its methods override
            for key in ns:
                _n.patched_class(cls, key)

    def __setattr__(cls, name, value):
        super().__setattr__(name, value)
        _n.patched_class(cls, name)


class Object(metaclass=Meta):
    __kaliru_mirror__ = True
    __slots__ = ("_k_h", "__dict__", "__weakref__")

    def __setattr__(self, name, value):
        object.__setattr__(self, name, value)
        _n.patched_instance(self, name)


class Attr:
    __slots__ = ("id", "name")

    def __init__(self, id, name):
        self.id = id
        self.name = name

    def __get__(self, obj, cls=None):
        if obj is None:
            return self
        return _n.get(obj, self.id)

    def __set__(self, obj, value):
        _n.set(obj, self.id, value)

    def __delete__(self, obj):
        _n.delete(obj, self.id)


def module_getattr(modname):
    def __getattr__(name):
        return _n.module_value(modname, name)
    return __getattr__


class MirrorLoader(importlib.abc.Loader):
    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        code = compile(_n.source(name), "<kaliru mirror %s>" % (name,), "exec")
        exec(code, module.__dict__)


class MirrorFinder(importlib.abc.MetaPathFinder):
    def __init__(self, klippy_dir, modules):
        self.klippy_dir = klippy_dir
        self.modules = modules  # mirrored name -> is a package

    def find_spec(self, fullname, path=None, target=None):
        if not fullname.startswith("klippy.") and fullname != "klippy":
            # compat: a legacy top-level import of a klippy module
            if "klippy." + fullname in self.modules or self._file("klippy." + fullname):
                importlib.import_module("klippy." + fullname)
                return importlib.util.spec_from_loader(fullname, _AliasLoader("klippy." + fullname))
            return None
        if fullname not in self.modules:
            return None  # a file under the klippy directory (normal path finder)
        is_pkg = self.modules[fullname]
        spec = importlib.machinery.ModuleSpec(fullname, MirrorLoader(), is_package=is_pkg)
        if is_pkg:
            # third-party modules in extras/, plugins/, ... are found here
            rel = fullname.split(".")[1:]
            spec.submodule_search_locations = [os.path.join(self.klippy_dir, *rel)]
        return spec

    def _file(self, fullname):
        rel = os.path.join(self.klippy_dir, *fullname.split(".")[1:])
        return os.path.isfile(rel + ".py") or os.path.isfile(os.path.join(rel, "__init__.py"))


class _AliasLoader(importlib.abc.Loader):
    def __init__(self, target):
        self.target = target

    def create_module(self, spec):
        return sys.modules[self.target]

    def exec_module(self, module):
        pass


def install(klippy_dir, modules):
    sys.meta_path.insert(0, MirrorFinder(klippy_dir, dict(modules)))
